template.script:
(function () {
    var overlay = document.getElementById('etp-zoom-overlay');
    if (!overlay || overlay.dataset.etpZoomReady) { return; }
    overlay.dataset.etpZoomReady = '1';

    var stage = overlay.querySelector('.etp-zoom-stage');
    var img = overlay.querySelector('.etp-zoom-img');
    var MIN = 1, MAX = 6, STEP = 0.4;
    var scale = 1, tx = 0, ty = 0;
    var baseW = 0, baseH = 0;
    var dragging = false, moved = false;
    var startX = 0, startY = 0, startTx = 0, startTy = 0;

    function clamp(v, lo, hi) { return Math.min(hi, Math.max(lo, v)); }

    // keep the image from being dragged entirely out of view
    function constrain() {
        var maxX = Math.max(0, (baseW * scale - baseW) / 2 + 40);
        var maxY = Math.max(0, (baseH * scale - baseH) / 2 + 40);
        tx = clamp(tx, -maxX, maxX);
        ty = clamp(ty, -maxY, maxY);
    }

    function apply() {
        constrain();
        img.style.transform =
            'translate(' + tx + 'px, ' + ty + 'px) scale(' + scale + ')';
        overlay.classList.toggle('is-zoomed', scale > 1.001);
    }

    function reset() { scale = 1; tx = 0; ty = 0; apply(); }

    // zoom toward a point (cx, cy) measured from the stage centre,
    // keeping that point visually fixed (cursor-anchored zoom).
    function zoomTo(next, cx, cy) {
        next = clamp(next, MIN, MAX);
        if (!(Math.abs(next - scale) > 0.0001)) { return; }
        var ratio = next / scale;
        tx = cx - ratio * (cx - tx);
        ty = cy - ratio * (cy - ty);
        scale = next;
        if (!(scale > MIN + 0.0001)) { tx = 0; ty = 0; }
        apply();
    }

    function stageCenter(e) {
        var r = stage.getBoundingClientRect();
        return {
            x: e.clientX - (r.left + r.width / 2),
            y: e.clientY - (r.top + r.height / 2)
        };
    }

    function open(src, alt) {
        if (!src) { return; }
        img.src = src;
        img.alt = alt || '';
        overlay.classList.add('is-open');
        overlay.setAttribute('aria-hidden', 'false');
        document.body.classList.add('etp-zoom-lock');
        reset();
        var c = overlay.querySelector('.etp-zoom-close');
        if (c) { try { c.focus(); } catch (err) {} }
    }

    function close() {
        overlay.classList.remove('is-open');
        overlay.classList.remove('is-zoomed');
        overlay.setAttribute('aria-hidden', 'true');
        document.body.classList.remove('etp-zoom-lock');
        scale = 1; tx = 0; ty = 0;
        img.style.transform = '';
        img.removeAttribute('src');
    }

    img.addEventListener('load', function () {
        baseW = img.clientWidth || img.naturalWidth || 0;
        baseH = img.clientHeight || img.naturalHeight || 0;
    });

    // bind each thumbnail (left-click / Enter / Space). We read the
    // inner img's existing src — we never change it, never open it
    // in a new tab, and never add an anchor.
    function bindThumb(el) {
        if (el.dataset.etpZoomBound) { return; }
        el.dataset.etpZoomBound = '1';
        var thumb = el.querySelector('img');
        if (!thumb) { return; }
        function go() {
            open(thumb.getAttribute('src'), thumb.getAttribute('alt'));
        }
        el.addEventListener('click', function (e) {
            e.preventDefault();
            go();
        });
        el.addEventListener('keydown', function (e) {
            if (e.key === 'Enter' || e.key === ' ' ||
                e.key === 'Spacebar') {
                e.preventDefault();
                go();
            }
        });
    }
    Array.prototype.forEach.call(
        document.querySelectorAll('.etp-image-zoomable'), bindThumb);

    // toolbar + backdrop. All controls are type=button and the
    // overlay lives OUTSIDE #etp-response-form, so nothing here can
    // submit the exam form.
    overlay.addEventListener('click', function (e) {
        var btn = e.target.closest ?
            e.target.closest('[data-etp-zoom-action]') : null;
        if (btn) {
            e.preventDefault();
            var a = btn.getAttribute('data-etp-zoom-action');
            if (a === 'in') { zoomTo(scale + STEP, 0, 0); }
            else if (a === 'out') { zoomTo(scale - STEP, 0, 0); }
            else if (a === 'reset') { reset(); }
            else if (a === 'close') { close(); }
            return;
        }
        if (!moved && (e.target === overlay || e.target === stage)) {
            close();
        }
    });

    // cursor-anchored wheel zoom; preventDefault only while open so
    // normal page scrolling is untouched the rest of the time.
    stage.addEventListener('wheel', function (e) {
        if (!overlay.classList.contains('is-open')) { return; }
        e.preventDefault();
        var c = stageCenter(e);
        var dir = e.deltaY > 0 ? -1 : 1;
        zoomTo(scale + dir * STEP, c.x, c.y);
    }, { passive: false });

    // drag to pan (pointer events cover mouse + touch)
    stage.addEventListener('pointerdown', function (e) {
        if (!(scale > 1.001)) { return; }
        dragging = true; moved = false;
        startX = e.clientX; startY = e.clientY;
        startTx = tx; startTy = ty;
        try { stage.setPointerCapture(e.pointerId); } catch (err) {}
        stage.classList.add('is-grabbing');
    });
    stage.addEventListener('pointermove', function (e) {
        if (!dragging) { return; }
        var dx = e.clientX - startX, dy = e.clientY - startY;
        if (Math.abs(dx) > 3 || Math.abs(dy) > 3) { moved = true; }
        tx = startTx + dx; ty = startTy + dy;
        apply();
    });
    function endDrag(e) {
        if (!dragging) { return; }
        dragging = false;
        stage.classList.remove('is-grabbing');
        try { stage.releasePointerCapture(e.pointerId); } catch (err) {}
        setTimeout(function () { moved = false; }, 0);
    }
    stage.addEventListener('pointerup', endDrag);
    stage.addEventListener('pointercancel', endDrag);

    // double-click toggles a quick 2.5x at the cursor
    stage.addEventListener('dblclick', function (e) {
        e.preventDefault();
        var c = stageCenter(e);
        if (scale > 1.001) { reset(); }
        else { zoomTo(2.5, c.x, c.y); }
    });

    // keyboard: Esc closes, +/-/0 zoom. Scoped to when open so it
    // never steals keys from the exam form or proctoring handlers.
    document.addEventListener('keydown', function (e) {
        if (!overlay.classList.contains('is-open')) { return; }
        if (e.key === 'Escape') { e.preventDefault(); close(); }
        else if (e.key === '+' || e.key === '=') {
            e.preventDefault(); zoomTo(scale + STEP, 0, 0);
        } else if (e.key === '-' || e.key === '_') {
            e.preventDefault(); zoomTo(scale - STEP, 0, 0);
        } else if (e.key === '0') { e.preventDefault(); reset(); }
    });
})();

t.script:
(function () {
    var block = document.querySelector('.etp-label-block');
    var list = document.getElementById('etp-label-list');
    if (!block) { return; }
    if (!list) { return; }
    var rows = Array.prototype.slice.call(
        list.querySelectorAll('.etp-label-row'));
    var counter = document.getElementById('etp-label-counter');
    var pager = document.getElementById('etp-label-pager');
    var pageInfo = document.getElementById('etp-label-pageinfo');
    var prevBtn = document.getElementById('etp-label-prev');
    var nextBtn = document.getElementById('etp-label-next');
    var pageSize = parseInt(block.dataset.pageSize, 10) || 8;
    var total = rows.length;
    var pageCount = Math.ceil(total / pageSize) || 1;
    var page = 0;
    function answered() {
        var n = 0;
        rows.forEach(function (row) {
            var inp = row.querySelector('input');
            if (inp) {
                if ((inp.value || '').trim() !== '') { n += 1; }
            }
        });
        return n;
    }
    function updateCounter() {
        if (counter) {
            counter.textContent = answered() + ' / ' + total + ' labelled';
        }
    }
    function render() {
        var multi = (pageCount !== 1);
        rows.forEach(function (row, i) {
            var onPage = (Math.floor(i / pageSize) === page);
            row.classList.toggle('d-none', multi ? !onPage : false);
        });
        if (pager) { pager.hidden = !multi; }
        if (multi) {
            if (pageInfo) {
                var from = page * pageSize + 1;
                var to = Math.min((page + 1) * pageSize, total);
                pageInfo.textContent = 'Boxes ' + from + '\u2013' + to + ' of ' + total;
            }
            if (prevBtn) { prevBtn.disabled = (page === 0); }
            if (nextBtn) { nextBtn.disabled = (page + 1 === pageCount); }
        }
        updateCounter();
    }
    if (prevBtn) {
        prevBtn.addEventListener('click', function () {
            if (page !== 0) { page -= 1; render(); block.scrollIntoView({block: 'nearest'}); }
        });
    }
    if (nextBtn) {
        nextBtn.addEventListener('click', function () {
            if (page + 1 !== pageCount) { page += 1; render(); block.scrollIntoView({block: 'nearest'}); }
        });
    }
    list.addEventListener('input', updateCounter);
    render();
})();

(function () {
    var cfgEl = document.getElementById('etp-exam-config');
    var RULES = {};
    try { RULES = JSON.parse(cfgEl.dataset.rules || '{}'); }
    catch (e) { RULES = {}; }
    // Violation policy. cap === 0 means the FIRST violation
    // ends the exam (server: `not cap` branch). We show a live
    // running count so the candidate is never surprised.
    var vCap = parseInt(RULES.max_violations, 10) || 0;
    var vCount = parseInt(RULES.violation_count, 10) || 0;
    var vAuto = RULES.violation_action === 'auto_submit';
    var vBanner = document.getElementById('etp-violation-banner');
    var vMsg = document.getElementById('etp-violation-msg');
    function showViolationBanner(text) {
        if (!vBanner || !vMsg) { return; }
        vMsg.textContent = text;
        vBanner.classList.remove('d-none');
    }
    function violationText(n) {
        // n = the count INCLUDING the one just detected.
        if (vAuto && (vCap === 0 || n >= vCap)) {
            return 'Proctoring violation detected. Your exam is being submitted.';
        }
        if (vCap > 0) {
            return 'Warning: proctoring violation ' + n + ' of ' +
                   vCap + '. Your exam auto-submits at ' + vCap + '.';
        }
        return 'Warning: proctoring violation recorded (' + n + ').';
    }
    // Persisted reminder: if the server already counted prior
    // violations for this attempt, surface them on load.
    if (vCount > 0) { showViolationBanner(violationText(vCount)); }
    function reportViolation(reason) {
        // Live running count for the candidate banner (client
        // display only; the server stays the source of truth
        // for enforcement).
        vCount += 1;
        showViolationBanner(violationText(vCount));
        // Use sendBeacon: a synchronous form POST fired from
        // inside visibilitychange / unload is frequently
        // DROPPED by the browser when the tab backgrounds, so
        // the violation never reached the server and
        // auto-submit never triggered. sendBeacon is delivered
        // even while the page is being hidden/unloaded.
        var url = document.getElementById('etp-violation-form').action;
        var sent = false;
        try {
            if (navigator.sendBeacon) {
                var fd = new FormData();
                fd.append('csrf_token',
                    document.querySelector('#etp-violation-form input[name=csrf_token]').value);
                fd.append('violation_reason', reason);
                sent = navigator.sendBeacon(url, fd);
            }
        } catch (e) { sent = false; }
        if (!sent) {
            // Fallback: hidden-form POST (navigates the page).
            try {
                document.getElementById('etp-violation-reason').value = reason;
                document.getElementById('etp-violation-form').submit();
                return;
            } catch (e2) { console.warn('violation post failed', e2); }
        }
        // DO NOT reload here. Enforcement is entirely
        // server-side (_record_violation_single auto-submits
        // at max_violations, and every later POST is
        // is_locked-guarded), so a reload adds nothing to it
        // — it only destroyed whatever the candidate had
        // typed, on EVERY violation: a right-click, a paste
        // reflex, a tab switch. A terminated candidate simply
        // lands on the locked page at their next navigation.
        notifyViolation(reason);
    }
    // Non-destructive, self-clearing notice. Never touches
    // the form or navigates.
    function notifyViolation(reason) {
        var el = document.getElementById('etp-violation-note');
        if (!el) { return; }
        el.textContent = 'Proctoring: ' + reason +
            ' — this has been recorded.';
        el.classList.remove('d-none');
        clearTimeout(el._t);
        el._t = setTimeout(function () {
            el.classList.add('d-none');
        }, 4000);
    }
    if (RULES.right_click) {
        document.addEventListener('contextmenu', function (e) {
            e.preventDefault();
            reportViolation('Right-click attempted');
        });
    }
    if (RULES.copy_paste) {
        ['copy', 'cut', 'paste'].forEach(function (ev) {
            document.addEventListener(ev, function (e) {
                e.preventDefault();
                reportViolation('Clipboard action: ' + ev);
            });
        });
    }
    if (RULES.tab_switch) {
        var blurredAt = 0;
        document.addEventListener('visibilitychange', function () {
            if (document.hidden && Date.now() - blurredAt > 1500) {
                blurredAt = Date.now();
                reportViolation('Tab switched / window hidden');
            }
        });
    }
    if (RULES.devtools) {
        // ZOOM SAFETY: innerWidth is CSS pixels and SHRINKS as
        // the candidate zooms in, while outerWidth does not —
        // so the raw delta grew with zoom and a low-vision
        // candidate at 150% tripped the old 200px threshold
        // (delta ~480 on a 1440px window) and was auto-
        // submitted for cheating. devicePixelRatio moves with
        // zoom, so normalising by it cancels the zoom out.
        // Compare against the ratio captured at load rather
        // than assuming the candidate starts at 100%.
        var baseDpr = window.devicePixelRatio || 1;
        var devtoolsReported = false;
        setInterval(function () {
            var zoom = (window.devicePixelRatio || 1) / baseDpr;
            var w = window.outerWidth - window.innerWidth * zoom;
            var h = window.outerHeight - window.innerHeight * zoom;
            // Threshold raised: a docked panel is >=250px, and
            // guessing wrong here ENDS someone's exam.
            if (!devtoolsReported && (w > 300 || h > 300)) {
                devtoolsReported = true;
                reportViolation('Developer tools detected');
            }
        }, 2000);
    }
    if (RULES.screenshot) {
        document.addEventListener('keyup', function (e) {
            if (e.key === 'PrintScreen') {
                reportViolation('Screenshot key pressed');
            }
        });
    }
    // ---- Watermark: faint identity overlay that deters
    // photographing the questions. Pointer-events:none so it
    // never blocks answering. textContent (not innerHTML) so
    // the label cannot inject markup.
    if (RULES.watermark && RULES.watermark_label) {
        (function () {
            var layer = document.createElement('div');
            layer.className = 'etp-watermark-layer';
            layer.setAttribute('aria-hidden', 'true');
            for (var i = 0; i < 60; i++) {
                var cell = document.createElement('span');
                cell.className = 'etp-watermark-cell';
                cell.textContent = RULES.watermark_label;
                layer.appendChild(cell);
            }
            document.body.appendChild(layer);
        })();
    }
    // ---- Fullscreen: prompt the candidate into fullscreen and
    // treat leaving it as a violation. Browsers only allow
    // requestFullscreen from a user gesture, so we cannot force
    // it silently - we show a dismissable prompt with a button,
    // and once in fullscreen, an exit fires reportViolation.
    if (RULES.fullscreen) {
        (function () {
            var docEl = document.documentElement;
            function isFs() {
                return !!(document.fullscreenElement ||
                          document.webkitFullscreenElement);
            }
            function reqFs() {
                var fn = docEl.requestFullscreen ||
                         docEl.webkitRequestFullscreen;
                if (fn) {
                    try { fn.call(docEl); } catch (e) {}
                }
            }
            var prompt = document.getElementById('etp-fs-prompt');
            var btn = document.getElementById('etp-fs-btn');
            function showPrompt() {
                if (prompt) { prompt.classList.remove('d-none'); }
            }
            function hidePrompt() {
                if (prompt) { prompt.classList.add('d-none'); }
            }
            if (btn) {
                btn.addEventListener('click', function () {
                    reqFs();
                    hidePrompt();
                });
            }
            // Flag an EXIT only after entering fullscreen at
            // least once, so declining the initial prompt is
            // not itself a violation (which would auto-submit
            // on load at cap 0).
            var everEntered = false;
            function onFsChange() {
                if (isFs()) {
                    everEntered = true;
                    hidePrompt();
                } else if (everEntered) {
                    reportViolation('Exited fullscreen');
                    showPrompt();
                }
            }
            document.addEventListener('fullscreenchange', onFsChange);
            document.addEventListener('webkitfullscreenchange', onFsChange);
            showPrompt();
        })();
    }
    // ---- Webcam: request camera access on load. A denial or a
    // later track-ended (camera unplugged / permission revoked)
    // is a proctoring violation. The stream is kept open only to
    // detect loss; no frames are captured or uploaded.
    if (RULES.webcam) {
        (function () {
            var note = document.getElementById('etp-webcam-note');
            function showNote(msg) {
                if (!note) { return; }
                note.textContent = msg;
                note.classList.remove('d-none');
            }
            if (!navigator.mediaDevices ||
                !navigator.mediaDevices.getUserMedia) {
                reportViolation('Webcam unavailable in browser');
                showNote('This exam requires a webcam and your ' +
                         'browser does not provide one.');
                return;
            }
            navigator.mediaDevices.getUserMedia({ video: true })
                .then(function (stream) {
                    showNote('Webcam active for proctoring.');
                    stream.getVideoTracks().forEach(function (tr) {
                        tr.addEventListener('ended', function () {
                            reportViolation('Webcam disconnected');
                        });
                    });
                })
                .catch(function () {
                    reportViolation('Webcam access denied');
                    showNote('Webcam access was denied. This has ' +
                             'been recorded for proctoring.');
                });
        })();
    }
    // Countdown timer. data-deadline is UTC ISO 8601.
    var t = document.getElementById('etp-timer');
    var tAlert = document.getElementById('etp-timer-alert');
    if (t && t.dataset.deadline) {
        var deadline = new Date(t.dataset.deadline);
        var fired = false, warned5 = false, warned1 = false;
        function announce(msg) {
            if (tAlert) { tAlert.textContent = msg; }
        }
        function tick() {
            var ms = deadline - new Date();
            if (ms <= 0) {
                t.textContent = '00:00';
                t.classList.remove('bg-light', 'bg-warning', 'text-dark', 'border', 'etp-timer-warn');
                t.classList.add('bg-danger', 'text-white', 'etp-timer-critical');
                if (!fired) {
                    fired = true;
                    announce('Time is up. Submitting your assessment.');
                    document.getElementById('etp-response-form').submit();
                }
                return;
            }
            // Low-time warnings: amber emphasis at 5 min, red at 1 min.
            if (ms <= 60000 && !warned1) {
                warned1 = true;
                t.classList.remove('bg-light', 'bg-warning', 'border');
                t.classList.add('bg-danger', 'text-white', 'etp-timer-critical');
                announce('One minute remaining.');
            } else if (ms <= 300000 && !warned5) {
                warned5 = true;
                t.classList.remove('bg-light', 'border');
                t.classList.add('bg-warning', 'etp-timer-warn');
                announce('Five minutes remaining.');
            }
            var mm = Math.floor(ms / 60000);
            var ss = Math.floor((ms % 60000) / 1000);
            t.textContent = (mm < 10 ? '0' : '') + mm + ':' +
                            (ss < 10 ? '0' : '') + ss;
        }
        tick();
        setInterval(tick, 1000);
    }
    // Previous nav: save current answer then go back.
    var prevBtn = document.getElementById('etp-prev-btn');
    if (prevBtn) {
        prevBtn.addEventListener('click', function () {
            document.getElementById('etp-nav').value = 'prev';
        });
    }
    // Review nav: save current answer THEN review. This was a
    // plain link, so the in-progress answer was lost on click.
    var reviewBtn = document.getElementById('etp-review-btn');
    if (reviewBtn) {
        reviewBtn.addEventListener('click', function () {
            document.getElementById('etp-nav').value = 'review';
        });
    }

    // ---- Real-time progress (client-side visual aid only) ----
    // Purely cosmetic: never mutates submitted data, never
    // gates required fields, never blocks navigation/submit.
    // One-question-per-page exam: the confirmed bar width is
    // server-driven (answered questions / total). Here we (a)
    // show a live "X / N answered on this page" readout by
    // grouping the page's answer controls by their existing
    // name attribute, and (b) advance the bar by exactly one
    // question's share the moment the page is fully answered —
    // but only if it wasn't already answered at load (already
    // counted server-side), so it never double-counts.
    (function () {
        var form = document.getElementById('etp-response-form');
        var track = document.querySelector('.etp-progress--live');
        var bar = track ? track.querySelector('.progress-bar') : null;
        if (!form || !track || !bar) { return; }
        var pctEl = document.getElementById('etp-progress-pct');
        var pageEl = document.getElementById('etp-page-answered');
        var pageTxt = pageEl ? pageEl.querySelector('.etp-page-answered-text') : null;
        var pageIcon = pageEl ? pageEl.querySelector('i') : null;
        var total = parseInt(track.dataset.total, 10) || 0;
        var basePercent = parseInt(track.dataset.basePercent, 10) || 0;
        // Non-answer control names that must be ignored.
        var IGNORE = { csrf_token: 1, question_id: 1, nav: 1,
                       violation_reason: 1 };

        function answerGroups() {
            // Group visible named answer controls by name so a
            // multi-radio/checkbox set counts as ONE group.
            var map = {};
            var els = form.querySelectorAll(
                'input[name], textarea[name], select[name]');
            for (var i = 0; i < els.length; i++) {
                var el = els[i];
                var nm = el.name;
                if (!nm || IGNORE[nm] || el.type === 'hidden') {
                    continue;
                }
                (map[nm] = map[nm] || []).push(el);
            }
            return map;
        }
        function groupFilled(list) {
            for (var i = 0; i < list.length; i++) {
                var el = list[i];
                if (el.type === 'radio' || el.type === 'checkbox') {
                    if (el.checked) { return true; }
                } else if ((el.value || '').trim() !== '') {
                    return true;
                }
            }
            return false;
        }
        function tally() {
            var map = answerGroups();
            var names = Object.keys(map);
            var filled = 0;
            for (var i = 0; i < names.length; i++) {
                if (groupFilled(map[names[i]])) { filled++; }
            }
            return { total: names.length, filled: filled };
        }

        // Snapshot at load: if every group is already filled the
        // question is saved and already inside basePercent.
        var atLoad = tally();
        var answeredAtLoad = atLoad.total > 0 &&
                             atLoad.filled === atLoad.total;

        function recompute() {
            var t = tally();
            var n = t.total;
            var filled = t.filled;
            var complete = n > 0 && filled === n;
            if (pageTxt) {
                pageTxt.textContent = filled + ' / ' + n +
                    ' answered on this page';
            }
            if (pageEl) {
                pageEl.classList.toggle('is-complete', complete);
                pageEl.classList.toggle('is-started',
                                        filled > 0 && !complete);
            }
            if (pageIcon) {
                pageIcon.className = complete
                    ? 'fa fa-check-circle'
                    : (filled > 0 ? 'fa fa-adjust'
                                  : 'fa fa-circle-o');
            }
            var pct = basePercent;
            if (complete && !answeredAtLoad && total > 0) {
                pct = Math.min(100,
                    basePercent + Math.round(100 / total));
            }
            bar.style.width = pct + '%';
            track.classList.toggle('is-advancing',
                complete && !answeredAtLoad);
            if (pctEl) {
                pctEl.textContent = pct + '% complete';
            }
        }

        // Event delegation: one listener survives every input
        // type (radio, checkbox, textarea, text label inputs).
        form.addEventListener('input', recompute);
        form.addEventListener('change', recompute);
        recompute();
    })();
})();
